"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["54145"],{67280(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_em_branco","status":422,"titulo":"O pressuposto nomeia um fato"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_em_branco","requisitos":[],"oQueAconteceu":["A lista `pressupostos` do `conteudo` do modelo, enviada na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), tem um item vazio, s\xf3 com espa\xe7os ou `null`. Os pressupostos s\xe3o os fatos que o modelo recebe da inscri\xe7\xe3o, sem colet\xe1-los de novo, e cada um precisa nomear um fato.","A recusa vem na lista `errors` da resposta, com `field` igual a `conteudo.pressupostos[i]`, em que `i` \xe9 a posi\xe7\xe3o do item. Ela s\xf3 \xe9 conferida num modelo que n\xe3o \xe9 o de inscri\xe7\xe3o, porque este n\xe3o tem pressupostos (ver [modelo de inscri\xe7\xe3o sem pressupostos](/erros/uniplus.configuracao.modelo_formulario.pressuposto_na_inscricao)), e depois que o conte\xfado foi lido sem recusa de leitura. Nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Retire o item em branco da lista `pressupostos`, ou preencha-o com o c\xf3digo de um fato do cat\xe1logo coletado pela inscri\xe7\xe3o, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);